#include<bits/stdc++.h>
using namespace std;

int main(){
	string s;
	cin >> s;
	int x = s.find("|");  // 先頭から見て最初に '|' が現れる位置
	int y = s.rfind("|");  // 末尾から見て最初に '|' が現れる位置
	cout << s.substr(0,x) + s.substr(y+1) << endl;
}

#include<bits/stdc++.h>
using namespace std;

int main(){
	string s;
	cin >> s;
	string t;
	int count = 0;
	for(char c: s){
		if(c == '|'){
			count++;
		}else{
			if(count != 1) t+=c;
		}
	}
	cout << t << endl;
}
